style.css:
@-moz-document domain("youtube.com") {
/* Background and general layout */
  body {
    background-color: #f9f9f9;
    font-family: Arial, sans-serif;
  }

  /* Navigation Bar */
  #masthead-container {
    background-color: #ffffff;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1);
  }

  #logo {
    background-image: url('https://upload.wikimedia.org/wikipedia/commons/4/42/YouTube_icon_%282013-2017%29.png');
    background-size: contain;
    width: 90px;
    height: 40px;
  }

  #top-level-buttons-computed {
    margin-left: 20px;
  }

  #search {
    border-radius: 50px;
    border: 1px solid #ccc;
    background-color: #f1f1f1;
  }

  /* Sidebar */
  #guide {
    width: 240px;
    background-color: #ffffff;
    border-right: 1px solid #e0e0e0;
    box-shadow: 2px 0px 5px rgba(0, 0, 0, 0.1);
  }

  #guide-inner-content {
    padding-top: 10px;
  }

  #guide-inner-content .guide-section-title {
    font-size: 14px;
    color: #606060;
    text-transform: uppercase;
  }

  /* Video Page Layout */
  #content {
    margin-left: 260px;
  }

  /* Video Player */
  #player-container {
    border-radius: 4px;
    overflow: hidden;
  }

  /* Video Thumbnails */
  ytd-thumbnail {
    border-radius: 4px;
    overflow: hidden;
  }

  /* Video Title */
  #container {
    max-width: 85%;
    margin: 0 auto;
  }

  ytd-video-primary-info-renderer {
    font-family: 'Arial', sans-serif;
  }

  ytd-video-primary-info-renderer #title h1 {
    font-size: 20px;
    color: #333333;
  }

  ytd-video-primary-info-renderer #owner-name {
    color: #888888;
  }

  /* Description Box */
  #description {
    color: #444444;
    font-size: 14px;
  }

  /* Footer */
  #footer {
    background-color: #f1f1f1;
    padding: 15px 0;
    font-size: 12px;
    color: #888888;
  }

  .yt-simple-endpoint {
    color: #0066cc;
  }

  /* Links */
  a {
    color: #0066cc;
    text-decoration: none;
  }

  a:hover {
    text-decoration: underline;
  }
}
